#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn ok_cases() {
        assert_eq!(parse_kv(" x = 42 "), Ok(("x".to_string(), 42)));
        assert_eq!(parse_kv("neg=-7"), Ok(("neg".to_string(), -7)));
    }

    #[test]
    fn errors() {
        assert_eq!(parse_kv("x 42"), Err(ParseError::MissingEquals));
        assert_eq!(parse_kv("  = 5"), Err(ParseError::EmptyKey));
        assert_eq!(parse_kv("y=abc"), Err(ParseError::BadValue("abc".to_string())));
        assert_eq!(parse_kv("y="), Err(ParseError::BadValue(String::new())));
    }

    #[test]
    fn splits_on_first_equals() {
        assert_eq!(parse_kv("a=1=2"), Err(ParseError::BadValue("1=2".to_string())));
    }

    #[test]
    fn parse_all_ok() {
        let text = "a=1\n\n  b = 2\nc=-3\n";
        assert_eq!(
            parse_all(text),
            Ok(vec![("a".to_string(), 1), ("b".to_string(), 2), ("c".to_string(), -3)])
        );
        assert_eq!(parse_all(""), Ok(vec![]));
    }

    #[test]
    fn parse_all_first_error() {
        let text = "a=1\nbad\nc=zz";
        assert_eq!(parse_all(text), Err(ParseError::MissingEquals));
    }
}
